mapper.select:
SELECT
,
tu.real_name AS teacherName,
d.dept_name AS deptName,
s.semester_name AS semesterName
FROM course c

WHERE c.deleted = 0

    AND c.course_name LIKE CONCAT('%', #{query.courseName}, '%')


    AND c.course_code LIKE CONCAT('%', #{query.courseCode}, '%')


    AND c.semester_id = #{query.semesterId}


    AND c.dept_id = #{query.deptId}


    AND c.teacher_id = #{query.teacherId}


    AND c.course_type = #{query.courseType}


    AND c.status = #{query.status}


    AND c.selected_count < c.max_capacity

ORDER BY c.semester_id DESC, c.id DESC

SELECT c.id AS courseId, c.course_name AS courseName, tu.real_name AS teacherName, c.max_capacity AS maxCapacity, c.selected_count AS selectedCount, ROUND(c.selected_count * 100.0 / NULLIF(c.max_capacity, 0), 1) AS rate FROM course c LEFT JOIN teacher t ON t.id = c.teacher_id AND t.deleted = 0 LEFT JOIN sys_user tu ON tu.id = t.user_id AND tu.deleted = 0 WHERE c.deleted = 0
AND c.semester_id = #{semesterId}
ORDER BY c.selected_count DESC, c.id ASC LIMIT #{limit}

SELECT d.dept_name AS name, COUNT(DISTINCT c.id) AS value FROM department d LEFT JOIN course c ON c.dept_id = d.id AND c.deleted = 0
AND c.semester_id = #{semesterId}
WHERE d.deleted = 0 GROUP BY d.id, d.dept_name ORDER BY value DESC
